    },
    orange: {
        background: 'bg-[#ff3d00]',
        overlay: 'bg-[radial-gradient(circle_at_20%_15%,rgba(255,255,255,0.2),transparent_32%),radial-gradient(circle_at_80%_5%,rgba(0,0,0,0.12),transparent_30%)]',
