const DEFAULT_PREVIEW_CARDS: ResourceCTAPreviewCard[] = [
    {
        title: 'Experiment Card',
        subtitle: 'Preview',
        icon: <span className="text-xl">🗒️</span>,
        color: 'bg-[#ff3d00]',
        textColor: 'text-white',
        rotationClass: 'rotate-[-6deg]',
    },
    {
        title: 'Decision Log',
        subtitle: 'Preview',
